/* Site-wide styles below. Vue custom elements have their own shadow-DOM styles,
   but content passed into their slots renders in the light DOM and is styled here. */

/* Block grid chrome. Views/Partials/blockgrid/ emits Umbraco's standard classes and
   CSS variables; this lays them out so the column spans editors pick are honoured. */
.umb-block-grid__layout-container {
    display: grid;
    grid-template-columns: repeat(var(--umb-block-grid--grid-columns, 12), minmax(0, 1fr));
}

.umb-block-grid__layout-item {
    grid-column-end: span min(var(--umb-block-grid--item-column-span, 12), var(--umb-block-grid--grid-columns, 12));
    grid-row-end: span var(--umb-block-grid--item-row-span, 1);
}

